class Solution {
public:
    int findMaxConsecutiveOnes(vector<int>& a) {
        int cur = 0, best = 0;
        for (int x : a) {
            cur = (x == 1) ? cur + 1 : 0;
            best = max(best, cur);
        }
        return best;
    }
};
