class Solution {
public:
    int maxPower(string s) {
        int cur = 1, best = 1;
        for (int i = 1; i < (int)s.size(); i++) {
            cur = (s[i] == s[i - 1]) ? cur + 1 : 1;
            best = max(best, cur);
        }
        return best;
    }
};
